import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
const t = key => app.translator.trans('ernestdefoe-espn-cfb-ticker.admin.settings.' + key);
/** Which ESPN scoreboards the bar shows, as tick boxes over one comma-joined setting. */
export default class LeaguePicker extends Component {
  chosen() {
    return String(this.attrs.value() || '').split(',').map(s => s.trim()).filter(Boolean);
  }
  toggle(key, on) {
    const chosen = this.chosen();
    this.attrs.value((on ? [...new Set([...chosen, key])] : chosen.filter(k => k !== key)).join(','));
  }
  view() {
    // From the server's list (extend.php), never a copy written here.
    const leagues = app.data.espnTickerLeagues || [];
    const chosen = this.chosen();
    return m('.Form-group.CfbTickerLeagues', [m('label', t('leagues_label')), m('.helpText', t('leagues_help')), leagues.map(key => m('label.checkbox', {
      key
    }, [m('input[type=checkbox]', {
      checked: chosen.includes(key),
      onchange: e => this.toggle(key, e.target.checked)
    }), t('league.' + key)]))]);
  }
}
flarum.reg.add('ernestdefoe-espn-cfb-ticker', 'admin/components/LeaguePicker', LeaguePicker);